import Foundation
import Testing
@testable import NPCore

/// The reader's words against the JavaScript that the Expo app and the web
/// run (Fixtures/reader-words.json, generated by scripts/make-reader-words.sh):
/// a word index must mean the same word on every client, because the
/// reading position (`lastWordIndex`) syncs between them.
@Suite("Reader words (same as the Expo app and the web)")
struct ReaderWordsTests {
    struct Fixture: Decodable {
        struct Paragraph: Decodable {
            let text: String
            let tokens: [Expected]
        }

        struct Expected: Decodable, Equatable, CustomStringConvertible {
            let kind: String
            let text: String
            var description: String { "\(kind):\(text)" }
        }

        struct Document: Decodable {
            let name: String
            let text: String
            let toc: [TocEntry]
            let pageMap: [PageAnchor]
            let pageCount: Int?
            let wordCount: Int
            /// [canonical paragraph, kind, text]
            let words: [[Field]]
        }

        enum Field: Decodable {
            case int(Int)
            case string(String)
            init(from decoder: Decoder) throws {
                let c = try decoder.singleValueContainer()
                if let i = try? c.decode(Int.self) { self = .int(i) } else { self = .string(try c.decode(String.self)) }
            }

            var int: Int? { if case .int(let i) = self { return i } else { return nil } }
            var string: String? { if case .string(let s) = self { return s } else { return nil } }
        }

        let paragraphs: [Paragraph]
        let documents: [Document]
    }

    static let fixture: Fixture = {
        let url = Bundle.module.url(forResource: "reader-words", withExtension: "json", subdirectory: "Fixtures")!
        return try! JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }()

    /// What the JavaScript records for a token (an empty island's LaTeX is "…").
    static func expected(_ t: ReaderWords.Token) -> Fixture.Expected {
        Fixture.Expected(kind: t.kind.rawValue, text: t.kind == .math && t.text.isEmpty ? "…" : t.text)
    }

    @Test func eachParagraphSplitsLikeTheExpoApp() {
        for p in Self.fixture.paragraphs {
            let got = ReaderWords.tokens(p.text).map(Self.expected)
            #expect(got == p.tokens, "\(p.text)")
        }
    }

    @Test func theReviewExampleHasSeventeenWords() {
        let p = #"The two-photon state ($\rho_{AB}$), the $x$-axis and $G^{(2)}(\tau)$; the rate $R = \eta^2 N$ is fixed."#
        let t = ReaderWords.tokens(p)
        #expect(t.count == 17)
        #expect(t.map(\.text).prefix(9) == ["The", "two-photon", "state", "(", "\\rho_{AB}", "),", "the", "x", "-axis"])
        // Spacing as written: "(" touches ρ, "),", and "-axis" touches x.
        #expect(t.map(\.spaceBefore).prefix(9) == [false, true, true, true, false, false, true, true, false])
    }

    @Test(arguments: ReaderWordsTests.fixture.documents.map(\.name))
    func everyDocumentsWordsMatchTheWeb(_ name: String) throws {
        let doc = try #require(Self.fixture.documents.first { $0.name == name })
        let built = ReaderWords.build(text: doc.text, toc: doc.toc, pageMap: doc.pageMap, pageCount: doc.pageCount)
        var got: [Fixture.Expected] = []
        var canonical: [Int] = []
        for (i, p) in built.enumerated() {
            for t in p.tokens {
                got.append(Self.expected(t))
                canonical.append(i)
            }
        }
        let expected = doc.words.map { Fixture.Expected(kind: $0[1].string ?? "", text: $0[2].string ?? "") }
        #expect(got.count == doc.wordCount)
        #expect(canonical == doc.words.map { $0[0].int ?? -1 })
        if let first = zip(got, expected).enumerated().first(where: { $0.element.0 != $0.element.1 }) {
            Issue.record("\(name): word \(first.offset) is \(first.element.0), the web has \(first.element.1)")
        }
        #expect(got == expected)
    }

    @Test func chapterTitlesAreKeptForShowing() {
        let doc = Self.fixture.documents.first { $0.name == "headings-structured" }!
        let built = ReaderWords.build(text: doc.text, toc: doc.toc, pageMap: doc.pageMap, pageCount: doc.pageCount)
        #expect(built.filter(\.isChapterTitle).map(\.text) == ["INTRODUCTION", "Chapter 2 Methods", "3 Results", "Part 5 Outlook"])
        #expect(built.allSatisfy { $0.isChapterTitle == $0.tokens.isEmpty })
    }

    @Test func equationsAndPDFMaths() {
        #expect(ReaderWords.blockMath("$$x^2$$") == "x^2")
        #expect(ReaderWords.blockMath(#"\[ a + b \]"#) == "a + b")
        #expect(ReaderWords.blockMath("$E = mc^2$") == "E = mc^2")
        #expect(ReaderWords.blockMath("$a$ and $b$") == nil)
        #expect(ReaderWords.blockMath("$$ $$") == nil)
        #expect(ReaderWords.isUnicodeMath("〈∆X 2 a 〉= 1 2 e −2r ≈ ∑ n ∂ ψ"))
        #expect(!ReaderWords.isUnicodeMath("The ∆ between the two runs was small, as expected."))
        #expect(ReaderWords.paragraphs("a\n\nb\r\n\r\nc\n \nd") == ["a", "b c d"])
    }
}
